import{a as ia,n as Dd,o as ky,r as Um,s as oa}from"./main-EED6XBNS.js";var o=(()=>{class E{static{this.ɵfac=function(l){return new(l||E)}}static{this.ɵcmp=Um({type:E,selectors:[[`app-mana-nyelo`]],decls:437,vars:0,consts:[[1,`page-body`],[1,`vege`],[1,`image-placeholder`],[`src`,`assets/mn1.png`,`alt`,`A csapat az alkonyi erdőben vándorol`],[`src`,`assets/mn2.png`,`alt`,`Isolde, a vörös köpenyes papnő és egyik társa az erdei ösvényen`],[`src`,`assets/mn4.png`,`alt`,`A csapat a hegyi alagút bejárata előtt`],[`src`,`assets/mn3.png`,`alt`,`Világító rúnák az alagút boltívein`],[`src`,`assets/mn6.png`,`alt`,`Rúnákkal faragott alagútfalak, a padlón idézőkör`],[`src`,`assets/mn5.png`,`alt`,`Árnydémonok rontanak a csapatra az alagútban`],[`src`,`assets/mn7.png`,`alt`,`A megidézett démonherceg a lángok közt harcoló csapat fölött`],[`src`,`assets/mn8.png`,`alt`,`A Vérmedence, közepén a kristályt tartó oszloppal`],[`src`,`assets/mn9.png`,`alt`,`A vér tükréből életre kelő árnyak`],[`src`,`assets/mn10.png`,`alt`,`Szellemi párviadal az illúziók ködében`],[`src`,`assets/mn11.png`,`alt`,`Arkanis bőrzsákba rejti a Vérmedence kristályát`],[`src`,`assets/mn12.png`,`alt`,`Az Élő Labirintus lüktető kapuja`],[`src`,`assets/mn13.png`,`alt`,`Lebegő kristály a labirintus közepén, körülötte a csapat`],[`src`,`assets/mn14.png`,`alt`,`A csapat közös varázslata a labirintus falai között`],[`src`,`assets/mn15.png`,`alt`,`A kinyílt kapun túl fénylő, oszlopos csarnok`],[`src`,`assets/mn19.png`,`alt`,`A kimerült csapat egyre mélyebbre halad az alagútban`],[`src`,`assets/mn16.png`,`alt`,`A Mana-nyelő a rúnákkal faragott csarnokban`],[`src`,`assets/mn17.png`,`alt`,`A csapat utolsó harca a Mana-nyelővel`],[`src`,`assets/mn18.png`,`alt`,`Isolde és Ardea utolsó ölelése`]],template:function(l,m){l&1&&(oa(0,`div`,0)(1,`section`)(2,`h1`,1),ky(3,`A mana-nyelő`),ia()(),oa(4,`div`,2),Dd(5,`img`,3),ia(),oa(6,`section`)(7,`h1`),ky(8,`Az Árnyékok Erdejében`),ia(),oa(9,`p`),ky(10,`Arkanis, a nekromanta, homlokát törölve pillantott a mellette haladó Lyrikre, a csapat vezetőjére. A nap már erősen lemenőben volt, de még így is tűzött, és a poros úton minden lépésük egyre nehezebbé vált. Arkanis tekintetében mégsem fáradtság tükröződött, inkább az a fajta nyugtalanság, amely a ragadozót jellemzi, miközben kivárja a támadásra alkalmas pillanatot.`),ia(),oa(11,`p`),ky(12,`– Mennyi idő még, amíg Erigowba érünk?`),ia(),oa(13,`p`),ky(14,`A vezér nyugtalanul válaszolt:`),ia(),oa(15,`p`),ky(16,`– Legalább egy nap, talán több. De az igazi célunk ott van, lentebb az úton, a hegy gyomrában – mutatott kelet felé, jó félórányi járóföldre maguk elé. – Jó lett volna korábban ideérni, most már kevés az időnk. Még ma lépnünk kell!`),ia(),oa(17,`p`),ky(18,`Arkanis gondolatai mélyén saját terveit szövögette. A nekromancia mestere volt, de nem mindig ez az út várt rá. Gyermekkorában egyszerű parasztfiú volt, akit a környék varázslói és papjai megvetettek és üldöztek. Egy éjjel, amikor az életéért menekült, rábukkant egy ősi, tiltott könyvre, amely mélységes sötétséget rejtett. A könyv feltárta előtte a halál erejét, és Arkanis nem habozott élni vele. Elhagyta emberi mivoltát, és elsajátította a könyv minden titkát, hogy hatalmát felhasználva bosszút álljon azokon, akik egykor megvetették. Azóta sötét szövetségeket kötött, és minden egyes napja arra szolgált, hogy még több erőt gyűjtsön magának, bármilyen árat kelljen is fizetnie érte.`),ia(),oa(19,`p`),ky(20,`Arkanis tisztában volt vele, hogy az Erigowba vezető küldetés csak álca, de mindenképpen részt kellett vennie rajta, hiszen ez is újabb lépcsőfok volt a hatalom felé vezető úton. Belátta, hogy céljához szüksége van a csapatra, de egyetlen pillanatra sem feledte, hogy végső soron mindenki csak eszköz a kezében. Még Lyrik, a lángok mestere és Isolde, a papnő is, akiket egyelőre hasznosnak talált. Ha eljön az idő, Arkanis egy percig sem habozott volna mindent feláldozni a céljaiért.`),ia(),oa(21,`p`),ky(22,`Arkanis, a számító és kíméletlen nekromanta, végignézett társain, akik szintén a hőséggel és a fáradtsággal küszködtek. Tekintete megakadt a mellette haladó nőn, aki látszólag mit sem érzékelt mindebből. Fekete haja lassan lobogott a szél játékos ujjai között, arcán megdöbbentő nyugalom ült. Ruhája – piros köpeny, selyemtunika és bőrnadrág – finoman lengett lépteinek ütemére. Oldalán két rapír lógott díszes bőrtokban. Ő volt Isolde, akiről a városokban azt pletykálták, hogy magas rangú kurtizánként él, mióta meghallotta Ellanának, a szerelem és a gyönyör istennőjének hívását, és a Lótusz Leányai közé állt.`),ia(),oa(23,`p`),ky(24,`Arkanis játszi könnyedséggel olvasott a nő elméjében: régi trükk, de semmit sem bízott a véletlenre, mióta egy küldetésen az a kráni pribék álmában akarta elvágni a torkát.`),ia(),oa(25,`p`),ky(26,`Isolde története a hajnalok titokzatos ködéből bontakozott ki: gyermekkorát a Gorviki birodalom egy sötét és díszes bordélyában töltötte. Akkoriban még Zarának hívták, és minden lépését úgy tanulta meg, mint egy táncot: az élet és a halál közötti finom egyensúlyt. Egy napon azonban egy részeg nemes brutális dühkitörése ráébresztette saját tehetetlenségére. Akkor és ott, míg a halál árnyéka közelített felé, megjelent előtte Ellana, és a gyengéd istennő hangja arra hívta, hogy ne kiszolgáltatottként, hanem az ő papnőjeként adjon szerelmet és gyönyört, és enyhítse mások fájdalmát, mielőtt az őt is elemésztené. Azóta papnőként járta a világot, igazi céljait azonban mindig a múltjából szőtt finom fátyol mögé rejtette.`),ia(),oa(27,`p`),ky(28,`Aztán ott volt a csoport vezetője, Lyrik, akivel szemben még pszi-mágiát sem kellett alkalmaznia. A tegnap esti tavernázáskor csak úgy jött a szó a férfi szájából, ahogy a heves folyam viszi a kavicsot. Arkanis megtudta, hogy Lyrik egy távoli hegyi faluból származik, amelyet a lángoló égbolt alatt perzselt fel a Toroni birodalom. A férfi maga volt a tűz megszelídített formája: hórihorgas orra és szúrós, színtiszta kék szemei csak fokozták a benyomást, hogy mindent lát és mindent tud. Durva fekete szövetből varrt ruháját tenyérnyi széles vörös öv fogta össze a derekán, ami csak még jobban kiemelte a feltűnő ellentétet külső hidegsége és belső lángja között. Fegyver helyett mindig is a mágia lángjait használta, ám ezek a lángok számára nem pusztán hétköznapi eszközök voltak, hanem a gyűlölet és a pusztítás fegyverei.`),ia(),oa(29,`p`),ky(30,`Lyrik nem volt mindig zsoldoskapitány. Egykor a falujában élt, és apja kovácsműhelyében dolgozott. A tűz és a fém iránti vonzalma akkor kezdődött, amikor gyerekként a műhely tüze mellett hallgatta apja történeteit. Egy éjszaka azonban, amikor vörösen izzott az égbolt, és ellenséges seregek vették körül a falut, Lyrik nem tehetett mást, mint hogy a lángok között meneküljön. Apja és minden, amit szeretett, elpusztult a tűzben. Lyrik azóta is magában hordozza ezt a tüzet, és csak az idő mutatja meg, hogy végül őt is megemészti-e.`),ia(),oa(31,`p`),ky(32,` Aztán ott volt egy rejtélyes nő, aki egyszerű harcosnak látszott, de valójában nem az volt. A többieket megtéveszthette a belőle áradó harci mágia egyszerű, lesarkított és bumszli formája, ám Arkanis is ismerte a sötét tanokat, és ha el akarta kerülni a kellemetlen kérdéseket, gyakran ő maga is élt ezzel a trükkel. Nem, dehogy harcos! A nő aurája a halál sugarait ontotta magából, elméjét pedig áttörhetetlennek látszó pajzs védte. Arcán könnyed, természetes mosoly ült, fekete szeme vörös hajának keretéből villant elő. Egyszerű bőrpáncélt viselt, hátán mágikus köpenyt. Kardja rövid volt, de a maga nemében gyönyörű. A tavernában Ardea Myrandaként mutatkozott be. `),ia(),oa(33,`p`),ky(34,`Arkanis tovább figyelte a csoport tagjait, és pillantása a két testvérre, Vorenre és Kaelre esett. Úgy néztek ki, mintha ikrek lettek volna: arcuk és öltözetük is szinte egyforma volt. Egyszerű, bokáig érő, durva szövésű kék köntöst viseltek, derekukon bőrövvel, amelyről hosszútőr lógott alá. Fejük tarkopasz volt, arcukat megfestette a nyomorgás, ezért vonásaik élesek voltak. Arkanis olvasott az elméjükben, és látott mindent, amit rejtegettek – leginkább az taszította, hogy lelkük tiszta volt, és teljes odaadással szolgálta Noirt, az igazság és a rend istenét.`),ia(),oa(35,`p`),ky(36,`Voren és Kael Noir papjaiként járták a világot, és mindenütt, ahol csak megfordultak, az igazságot és a rendet hirdették. Bár békés faluban nőttek fel, szüleik korán megtanították őket arra, hogy az élet nem mindig igazságos. Apjuk, az egyszerű, de bölcs pásztor, arra nevelte őket, hogy az igazság és a becsület mindennél fontosabb. Anyjuk, a falu gyógyítója, nap mint nap a szeretet és az önzetlenség példáját mutatta nekik. A testvérek fiatal koruktól fogva a jóság elkötelezettjei voltak, és megfogadták, hogy életüket a gyengék és az elnyomottak védelmének szentelik.`),ia(),oa(37,`p`),ky(38,`Voren, az idősebb és komolyabb testvér, mindig is a bölcsességet és az igazságot kereste. Elmélyülten tanulmányozta a világ működését, a természet törvényeit és az emberek közötti kapcsolatok igazságosságát. Számára az élet világos útmutatás volt, amelyet követni kellett, és mindennél fontosabbnak tartotta, hogy a jóság és a becsület győzedelmeskedjen. Hosszútőre nem csupán fegyver volt, hanem az igazság eszköze, amelyet csak akkor rántott elő, ha a gyengék és a rászorulók védelme megkövetelte.`),ia(),oa(39,`p`),ky(40,`Kael, a fiatalabb testvér, ugyanilyen eltökélt volt, de ő inkább a cselekvés embere volt. Míg Voren a bölcsességre és az elmélyülésre összpontosított, Kael mindig készen állt arra, hogy az igazságért harcoljon. Nem gyűlöletből vagy bosszúvágyból küzdött, hanem abból a mély meggyőződésből, hogy a jóság és a szeretet ereje legyőzi a világ minden gonoszságát. Számára a harc nem öncélú erőszak volt, hanem az igazság és a rend helyreállításának eszköze. Hosszútőrét ő is csak akkor használta, ha az ártatlanok és a béke védelme szükségessé tette.`),ia(),oa(41,`p`),ky(42,`Arkanis undorral nézte őket. Ezek a férfiak túlságosan egyszerűek voltak ahhoz, hogy végső céljaiban bármilyen szerepet játszhassanak, de tisztán érezte, hogy olyan erő lakozik bennük, amelyre még szüksége lehet. Tisztaságukat és becsületességüket pedig kihasználhatja, ha eljön a megfelelő pillanat. A jóság és a fény eszméi… Arkanis számára mindez csak eszköz volt a hatalom megszerzéséhez. A testvérek múltjából az is kiderült, hogy ügyes manipulációval könnyen irányíthatók.`),ia(),oa(43,`p`),ky(44,`A vezér, Lyrik, idegesen nézett végig a csapatán. – Mágusok helyett inkább egy csapatnyi harcost kellett volna hoznom – gondolta. Tudta, hogy útjuk végállomása a megrendelő szerint Erigow, de hogy lerövidítsék az utat, át kell kelniük egy hegyvidéken, ahol bármikor rajtuk üthetnek.`),ia(),oa(45,`p`),ky(46,` Az erdő mélyén sűrű csend ülte meg a levegőt, csak a madarak távoli csicsergése törte meg. Isolde, Ellana papnője, a többiektől kissé távolabb egy különös növényt vizsgálgatott, amely első ránézésre semmiben sem különbözött a közönséges mohától. Felszíne száraz volt, és egy hatalmas fa tövében nőtt, amely árnyékot vetett rá. Isolde már azon gondolkodott, hogy lefekszik és szunyókál egyet a fa alatt, amikor Ardea Myranda, a rejtélyes nő, hirtelen odalépett hozzá, durván megragadta a karját, és elrántotta a növénytől. `),ia(),oa(47,`p`),ky(48,`– Te bolond! Meg akarsz halni? Ez a Mérgezett Halálmoha. Ha csak egy kicsit is hozzáérsz, lassan ható mérge beléd szivárog, és harc közben gyengíteni fog. A bérgyilkosok más növényekkel keverve késleltetett halál okozására használják! – mondta Ardea Myranda határozottan, minden szavát alaposan megválogatva.`),ia(),oa(49,`p`),ky(50,`Isolde vállat vont, majd halvány mosollyal így szólt:`),ia(),oa(51,`p`),ky(52,`– Köszönöm, édes!`),ia(),oa(53,`p`),ky(54,` Lassan Ardea felé indult, és amikor már csak egy orrnyira volt tőle, kéjesen a fülébe suttogta: – Köszönöm! `),ia(),oa(55,`p`),ky(56,` Aztán ráérősen Ardea ajkához közelítette a száját. Az amazonnak álcázott nő megzabolázottan állt; megakadályozhatta volna a romantikus csókot, de nem volt kedve hozzá. A csók után Ardea köhintett egyet, majd parancsolta: `),ia(),oa(57,`p`),ky(58,`– Kérlek, menjünk vissza a többiekhez!`),ia(),oa(59,`p`),ky(60,`Isolde csendben bólogatott, majd követte Ardeát vissza a csapathoz. Útközben elgondolkodott a történteken. Sejtette, hogy Ardea nem egyszerű harcos, hanem valami sokkal veszélyesebb. A nő titokzatossága már az első pillanattól vonzotta, de most, hogy ilyen közel került hozzá, érezte, hogy valami mélyebb és sötétebb erő rejtőzik benne. `),ia(),oa(61,`p`),ky(62,` Ardea maga is meglepődött, amikor szinte már visszaérésük pillanatában a nekromanta nyugtalan, durva pszi-letapogatással végre áttörte a védelmét: a csóktól ellanyhult figyelme önkéntelenül is leengedte dinamikus pszi-pajzsait. `),ia(),oa(63,`div`,2),Dd(64,`img`,4),ia(),oa(65,`p`),ky(66,`Ezt a csatát megnyerte. Arkanis tudta, hogy Ardea sohasem ismerné be nyíltan, hogy áttörte mentális védőfalait, de innentől kezdve a háta mögé kell néznie, mert tarthat a lány bosszújától. – Ennyit megért az egész – dohogott mosolyogva magában a nekromanta.`),ia(),oa(67,`p`),ky(68,`A férfi azonnal rájött: jól tette, hogy ösztönösen tartott Ardea Myrandától, a vörös hajú, fekete szemű nőtől, akinek jelenléte már a kezdet kezdetén mély, nyugtalanító érzést keltett benne. Ardea látszólag egyszerű harcos volt, aki bőrpáncélba burkolózva haladt a csapat többi tagja között, a nekromanta azonban érzékelte, hogy ez csupán álca, amely mögött sokkal sötétebb erő lapul. `),ia(),oa(69,`p`),ky(70,` Ardea Myranda, akit sokan csak tűzvarázsló-boszorkánymesterként ismertek, hosszú és veszélyes úton jutott el odáig, ahol most tartott. Múltja homályos volt, hírneve azonban megelőzte, bár a tetteiről jóval többen hallottak, mint ahányan a nevét vagy az arcát ismerték. Egykor egy idős tűzvarázsló tanítványa volt, aki megtanította neki, hogyan kell uralni a lángok erejét. A tűz iránti vonzalmát egy gorviki boszorkány mélyítette tovább, aki nemcsak a tűz, hanem a sötét mágia mélyebb titkait is feltárta előtte. Ardea gyorsan tanult, és nemcsak varázsereje, hanem hidegvérű kegyetlensége is egyre nőtt. Első áldozata éppen régi mestere, az idős tűzvarázsló volt: könyörtelenül megölte, mert a boszorkány ezt az árat szabta titkos tudásáért. `),ia(),oa(71,`p`),ky(72,` A múlt árnyai azonban sosem hagyták el teljesen Ardeát. Minden újabb csatában, minden megölt ellenségben ott visszhangzottak megölt mesterének régi tanításai: „A harcos nem csupán karddal és pajzzsal harcol. Legfőbb fegyvere a becsület és az ész. Csak ezekkel lehet győzni, és csak ezek ötvözésével lehet forgatni a kardot.” Ardea számára azonban a becsület már régóta üres szó volt, amelyet feláldozott a túlélés és a hatalom oltárán. `),ia(),oa(73,`p`),ky(74,` Vándorlásai során Ardea számos veszélyes tájat bejárt Gorviktól Ediomandon át Kránig és a Taba El Ibara feltérképezetlen vidékeiig. Bárhol fordult meg, halál kísérte az útját, és akik látták, rettegve beszéltek róla. Suttogva emlegették, mint megállíthatatlan erőt, amely minden akadályt elsöpör az útjából. `),ia(),oa(75,`p`),ky(76,`Egy nap, amikor egy különösen veszélyes küldetésről tért vissza, titokzatos ajánlat keltette fel a figyelmét. Egy árnyékos alak kereste fel, és megbízást ajánlott neki: egy törpe építészmester elhallgattatását. A feladat egyszerű volt, a fizetség viszont, háromszáz aranypénz, hatalmas összegnek számított. Ardea elfogadta a megbízást, és az építészmester élete hamarosan véget ért. Ez az esemény azonban újabb sötét útra sodorta, amely egyre mélyebbre húzta a hatalom és a sötétség világába. `),ia(),oa(77,`p`),ky(78,`Ardea számára a mostani küldetés más volt, mint az eddigiek. Tudta, hogy amit vállalt, nem egyszerű feladat: ezúttal a saját végzetével is szembe kell néznie. Ahogy az esti sötétség körülvette őket, érezte, hogy minden tudására és erejére szüksége lesz, ha túl akarja élni a közelgő megpróbáltatásokat.`),ia(),oa(79,`p`),ky(80,`Lyrik néhány tucat szívdobbanás múlva összehívta a csapatot, és elrendelte az indulást. A hívó szó éppen akkor érte el a nekromantát, amikor a varázslataihoz gyűjtött manát, mivel a pszi-támadás eléggé megcsapolta a pszi-pontjait. Zsörtölődve gyűrte össze a formulát tartalmazó papírtekercset, és hangosan káromkodott:`),ia(),oa(81,`p`),ky(82,`– Hogy az inkvizíció gyóntatna meg, te eszelős!`),ia(),oa(83,`p`),ky(84,`Karikás szemei nem tették megnyerővé a külsejét, de nem is akart tetszeni senkinek. Fontosabb dolga volt, és abban máris sikerrel járt: kiderítette, mit titkol valójában az a rejtélyes nő. A manára most azért lett volna szüksége, hogy a varázslataira támaszkodhasson, ha megfogyatkozott pszi-pontjaival már nem tudná megtartani az elméjét védő pajzsokat; eddig a védelem szilárdan állt… de ki tudja, milyen ellentámadásra számíthat!`),ia(),oa(85,`p`),ky(86,`A csapat útnak indult a szűk, sötét alagút felé, amely a megbízó kikötése szerint az egyetlen útjuk volt Erigow felé. A sziklafalak közé szorult levegőt a mágia érezhető súlya töltötte meg, és mindannyian tudták, hogy az igazi kihívások még csak most kezdődnek.`),ia(),oa(87,`p`),ky(88,`Ahogy a csoport az alagút szája felé közeledett, vastagon rájuk telepedett a sötétség, és a lábuk alatt csikorgó kövek hangja visszhangzott. A sziklákon ismeretlen eredetű jelek világítottak, mintha követték volna őket. Arkanis ekkor suttogva megkérdezte Lyriket:`),ia(),oa(89,`p`),ky(90,`– Biztos vagy benne, hogy ez a helyes út? Miért bízunk meg abban az árnyékban, aki küldött minket?`),ia(),oa(91,`p`),ky(92,`Lyrik csak biccentett, arca azonban feszültséget tükrözött.`),ia(),oa(93,`p`),ky(94,`– A fizetség túl jó ahhoz, hogy kérdéseket tegyünk fel.`),ia(),oa(95,`p`),ky(96,`Azt már csak magában tette hozzá:`),ia(),oa(97,`p`),ky(98,`– Az Éjkő ereje minden kockázatot megér.`),ia(),oa(99,`p`),ky(100,`Aztán még odaszólt a csapatnak:`),ia(),oa(101,`p`),ky(102,`– Csak tartsuk nyitva a szemünket.`),ia(),oa(103,`p`),ky(104,`A csapat csendben haladt tovább, minden lépéssel közelebb kerülve a céljához és azokhoz az ismeretlen veszélyekhez, amelyeket az alagút árnyai rejtettek. Az út nemcsak testi megpróbáltatásokkal, hanem belső démonaikkal is próbára tette őket. Tudták, hogy Erigow távoli fényei csak egy sokkal sötétebb és veszedelmesebb küldetés kezdetét jelentik.`),ia()(),oa(105,`div`,2),Dd(106,`img`,5),ia(),oa(107,`section`)(108,`h2`),ky(109,`Az alagút szájában`),ia(),oa(110,`p`),ky(111,`Lyrik, a tűzvarázsló és a csapat vezetője, aggódva nézett végig a csoportján. Az elmúlt napok szakadatlan menetelése megviselte őket, most pedig a Daibol-hegység sötét, fenyegető vonulatai előtt álltak. A hegyek hatalmas, áthatolhatatlannak tűnő falat emeltek eléjük, mögötte pedig Erigow földje húzódott. – Harcosokat kellett volna hoznom… de a megrendelő valamiért a mágusokhoz ragaszkodott. No, mindegy, ők legalább gyorsabbak – gondolta Lyrik ismét, miközben felidézte megbízójuk szigorú utasítását, hogy csak ezen az útvonalon kelhetnek át.`),ia(),oa(112,`div`,2),Dd(113,`img`,6),ia(),oa(114,`p`),ky(115,`Útjuk célja egy veszélyes és nagy hatalmú mágikus tárgy, az Éjkő megszerzése volt. Bár egyszerűbb és biztonságosabb útvonalak is vezettek Erigow felé, megbízójuk külön kikötötte, hogy a Dwyll Unióból Davalonon és Harnamunon át jussanak el Gile-ig, majd a Var Beriz folyón átkelve egy ismeretlen hegyalagúton keresztül lépjenek Erigow területére. Lyrik jól tudta, hogy a szomszédos Ilanor felé is kerülhettek volna, de az legalább két-három hét késést jelentett volna, ami elfogadhatatlan lett volna a Mongeris városában rájuk váró megbízó számára. – Ezt az utat kell választanunk, nincs más lehetőségünk – zárta le magában a gondolatot.`),ia(),oa(116,`p`),ky(117,` Lyrik, aki értett valamelyest a muzsikáláshoz, víg erigowi dalba kezdett, hogy felvidítsa a csapatot. Ahogy beléptek az alagútba, hangja visszhangzott a falakon, és a dallam egy pillanatra elűzte a sötétség és a félelem nyomasztó érzését. – Nehéz út van mögöttünk, s nem hagyhatjuk, hogy a sötétség legyőzzön minket, mielőtt célba érünk – mondta Lyrik, mielőtt rázendített a pajzán dal utolsó strófájára. `),ia(),oa(118,`p`),ky(119,`Az alagút gyorsan elnyelte a kinti napfény utolsó morzsáit is: alig tettek meg egy kőhajításnyit, amikor a mágikus sötétség végleg elzárta őket a külvilágtól. A visszaút nemcsak veszélyes lett volna, hanem lehetetlen is: az ősi természetmágia elválasztotta őket a bejárattól, ahonnan jöttek. Nem maradt más választásuk, mint előrehaladni az alagút sötét mélyén. A levegő egyre nyomasztóbbá vált, mintha maga a föld akarná megfojtani őket. Néhány tucat lépésre a bejárattól rúnák villództak a kőfalon, sápadt bíbor fényük kísértetiesen táncolt a kövek között. Arkanis kráni démonidéző rúnáknak vélte őket, és baljós aurájuk minden kétségét eloszlatta: itt komoly veszély fenyegeti őket. `),ia(),oa(120,`div`,2),Dd(121,`img`,7),ia(),oa(122,`p`),ky(123,`Arkanis, a nekromanta, előrelépett, és figyelmeztette a többieket: – Ezek a jelek ősi rúnák, démonok idézésére használják őket. Legyetek készenlétben!`),ia(),oa(124,`p`),ky(125,` A figyelmeztetés hatására a csapat tagjai feszülten haladtak tovább. Isolde, aki a csoport közepén lépdelt, egyetlen pillantással felmérte a helyzetet. Hosszú fekete haja romantikus lassúsággal lebbent minden lépésénél, arca pedig szinte már kihívó nyugalmat sugárzott. Piros köpenye, selyemtunikája és bőrnadrágja most is selymesen simult rá, oldalán ott lógott a két elegánsan kidolgozott rapír. – Az isten sem hinné el róla, hogy kurtizán – futott át Arkanis fején, miközben tekintete egy röpke pillanatra megállt rajta.`),ia(),oa(126,`p`),ky(127,`A baljós csendet váratlan, éles, sikolyszerű hang törte meg, ahogy a rúnák fénye hirtelen felerősödött. Az alagút egy pillanatra mintha megremegett volna, majd ismét minden elcsendesedett.`),ia(),oa(128,`p`),ky(129,`– Csapda! – kiáltotta Lyrik körbenézve, de már késő volt. A falakból sötét árnyak váltak le – mintha a rúnák szellemei ébredtek volna fel –, és körülvették a csapatot. Ezek az árnyak azonban nem egyszerű lények voltak, hanem démonok, akiket a falak rég elfeledett áldozataik emlékeként őriztek meg. Arkanis nem rémült meg.`),ia(),oa(130,`div`,2),Dd(131,`img`,8),ia(),oa(132,`p`),ky(133,`– A Necrografia szerinti ötödik kategóriájú, újkori démonok, akiknek az asztrálteste még emlékszik emberi mivoltukra – motyogta maga elé, de a zajtól senki sem hallotta. – Mindegy, úgysem tudnátok segíteni… – tette hozzá halkan.`),ia(),oa(134,`p`),ky(135,`Az árnyak szinte azonnal támadásba lendültek, és örvénylő testükkel a csapatra zúdultak. A démonok alakja groteszk módon változott: hol többkarú szörnyekké, hol torz arcú bestiákká alakultak, a belőlük áradó sötét energia pedig fojtogatta a levegőt.`),ia(),oa(136,`p`),ky(137,`Arkanis azonnal cselekedett. Szemei éles fénnyel villantak meg, és egyetlen szó nélkül, pusztán egy különleges kézjelsor segítségével fekete kígyókat idézett, amelyek alighogy életre keltek, máris az árnyakra vetették magukat. Arkanis mágiája nyers, ősi és tisztán gonosz volt. A kígyók testéből tüskék nőttek ki, és átdöfték a démonokat, de azok újra meg újra összeálltak a fekete ködből.`),ia(),oa(138,`p`),ky(139,`– Ez nem lesz elég – morogta Arkanis, majd egy még sötétebb, mélyről feltörő varázslatot kezdett mormolni. – Démon ellen démont! – mondta, miközben feltörte lelkében az egyik pecsétet, és feláldozta három gyermeke lelkét, akiket csak azért vállalt, hogy fizetőeszközül szolgáljanak a gonosznak, ha valaha ilyen helyzetbe kerülne. Üzenete és segélykérése eljutott a pokol mélyére, ahol nagy meglepetésére egy Necrografia szerinti tizedik kategóriájú démonherceg fogadta el az alkut. Arkanis elméje egy pillanatra elhomályosult, ahogy a démonúr átvette a hatalmat a teste fölött.`),ia(),oa(140,`p`),ky(141,`Arkanis ajkáról halk morajlásként kezdett előtörni az ősi nyelvű varázsige, miközben testét teljesen átadta a démonhercegnek. Érezte, ahogy a lélekpecsét megtörik, és három gyermeke lelkének szentségtelen energiája a mélységbe száll, fizetségül a pokol kapuinál.`),ia(),oa(142,`p`),ky(143,`A démonúr, átvéve az uralmat Arkanis teste fölött, mély, suttogó hangon kezdett beszélni, ősi, ismeretlen erőket szabadítva fel:`),ia(),oa(144,`p`)(145,`em`),ky(146,`– Athanatos Ktísis, skotadiá flegómena, exelthete kai katastrépsate! Despota tes Abyssou, pyr kai thanatos, kataklysmós kai katarásmenos!`),ia()(),oa(147,`p`),ky(148,`A varázsige elhangzása után Arkanis keze a démonúr irányításával soha nem látott kézjelet formált. A levegő megremegett körülötte, mintha maga a világ szövete hajolt volna meg az idézett erő előtt.`),ia(),oa(149,`p`),ky(150,`A varázslat egyre hevesebben működött, az alagút kövei vörösen izzottak a démonherceg hatalmától. Arkanis érezte, hogy saját ereje érintetlen, és bár testét a démon irányította, tudata tiszta maradt, készen arra, hogy kihasználja a megkötött alkut. A démonherceg jelenléte szétzúzta a körülöttük tolongó démonok sorait, és azok nyüszítve, megsemmisülve hullottak vissza a sötétségbe.`),ia(),oa(151,`p`),ky(152,`Ez a hatalom azonban nemcsak pusztító volt: a varázslat súlya ott maradt a levegőben, és fenyegetően emlékeztette Arkanist a démonok világának álnok természetére. A csata még nem ért véget, de most soha nem látott erő állt a csapat oldalán.`),ia(),oa(153,`p`),ky(154,`A talaj megnyílt alattuk, és egy végtelennek tűnő szakadékból holt lelkek emelkedtek ki: a démonok egykori áldozatai, akik most fegyverként fordultak az árnyak ellen, amelyeknek addig szolgálniuk kellett.`),ia(),oa(155,`p`),ky(156,`A démonok azonban nem adták fel, újabb rohamra készültek. A pokoli segítség immár véget ért: a paktum mindkét fél részéről teljesült. Arkanis jól tudta, hogy a démoni szövetségesek csak a kérés betűjéhez tartják magukat, nem a szelleméhez, így nem is remélte, hogy a segítség kitart a harc végéig. Most ismét egyedül kellett szembenézniük a rémálmok seregével.`),ia(),oa(157,`p`),ky(158,`Újabb démonok tűntek fel. Arkanis felismerte őket: hetedik kategóriájú, régi démonok voltak, varázserővel és romlott lélekcsonkkal, minden emberi vonástól megfosztva.`),ia(),oa(159,`p`),ky(160,`Isolde sem tétlenkedett. Rapírjai vakító kék fényben izzottak, ahogy a démonok felé lendült. – Fagyasztó Káosz! – kiáltotta, és a pengék nyomán fagyos szélvihar támadt, amely jéggé dermesztette a démonokat. Az árnyak egy pillanatra megtorpantak, de hamarosan újra összeálltak a tiszta sötétségből. Isolde szívósan küzdött, minden mozdulatát egyedi, pontos varázslat hatotta át, amely nemcsak sebzett, hanem az árnyak erejét is megtörte. `),ia(),oa(161,`div`,2),Dd(162,`img`,9),ia(),oa(163,`p`),ky(164,`Lyrik közben izzó, kavargó tűzlabdákat idézett, amelyek lávává olvasztották az alagút köveit. Egy szárnyas árnylénynek megperzselte a szárnyát, de az lélektelenül tovább támadott.`),ia(),oa(165,`p`),ky(166,`– Ez nem fog megállítani minket! – üvöltötte, és a tűz, mintha Lyrik véréből táplálkozott volna, még erősebben lobogott, egyre szorosabb gyűrűbe fogva a csapatot, mintha szentélyt emelt volna köréjük.`),ia(),oa(167,`p`),ky(168,`Ardea Myranda egy sötét, kavargó füstből álló démont vágott át a kardjával, és a lény a penge érintésétől szinte szétrobbant. Ez a démon azonban csak a kezdet volt. Az alagút mélyéből hatalmas, többfejű árnylény bukkant elő, amely sokkal erősebb és baljósabb volt a többinél. Ardea szemében egy pillanatra kétely villant, de gyorsan elhessegette. Mélyen összpontosított, és erőteljes, vakítóan fehér fényt idézett a kardjára, amely áttörte az árnylény pajzsát, és darabokra zúzta a szörnyet.`),ia(),oa(169,`p`),ky(170,`Voren és Kael tökéletes összhangban mozogtak: egy újabb démon árnyékát vágták ketté.`),ia(),oa(171,`p`),ky(172,`– Most együtt! – kiáltotta Voren, és mindketten egy mágikus rúnával erősítették meg a pengéjüket. Egyetlen villámgyors mozdulattal egyszerre döfték tőrüket a szörnybe, amely sikoltva foszlott semmivé.`),ia(),oa(173,`p`),ky(174,`Az árnyak megrohamozták Arkanist is, de a nekromanta egyetlen pillantással csontvázakat idézett, amelyek áttörték a démonok vonalát.`),ia(),oa(175,`p`),ky(176,`– Túl sokan vannak! – morogta, de szavai ellenére tovább harcolt, elméjében már a következő varázslatot tervezve. Összegyűjtötte minden sötét erejét, majd hatalmas hullámot szabadított el, amely végigsöpört az egész alagúton. A démonok sikoltozva szóródtak szét, mintha maga a sötétség fújt volna visszavonulót.`),ia(),oa(177,`p`),ky(178,`A démonok egy pillanatra megtorpantak, mintha érezték volna, hogy vesztésre állnak, de nem vonultak vissza. Ehelyett utolsó, kétségbeesett rohamra indultak. Az alagút megremegett, és hatalmas sziklaomlás zárta el mögöttük az utat.`),ia(),oa(179,`p`),ky(180,`– Tovább kell mennünk, most! – kiáltotta Lyrik, és tűzgömböt hajított a megmaradt árnyakra; a csapat szinte egyszerre tört át a démonok maradék sorain.`),ia(),oa(181,`p`),ky(182,`Kimerülten, de elszántan törtek előre a sötétségben, ahogy az alagút egyre mélyebbre vezette őket. Tudták, hogy az Éjkő megszerzése minden eddiginél nagyobb áldozatot követelhet. A harcok még nem értek véget, az alagút mélyén számtalan sötét lény várt rájuk. A visszaút már régen eltűnt a homályban, a cél felé vezető út viszont annál világosabban rajzolódott ki előttük.`),ia()(),oa(183,`section`)(184,`h2`),ky(185,`A Vérmedence`),ia(),oa(186,`p`),ky(187,`A csapat egyre mélyebbre hatolt az alagútban, a falak pedig egyre szűkebbek és nyirkosabbak lettek. A levegő nehéz volt a penész és a bomlás szagától, és lépteik ütemes visszhangja csak fokozta a hely nyomasztó csendjét.`),ia(),oa(188,`p`),ky(189,`Végül újabb akadályhoz értek. Az alagút hirtelen kiszélesedett, és hatalmas, vérrel teli medence tárult fel előttük. Éles pereme kiemelkedett a környező sziklák közül, mintha masszív kőmeder tartotta volna vissza a benne lappangó, nyugtalanító folyadékot. A vér sötét, feketevörös felszíne mozdulatlan volt, mintha végtelen mélységet rejtene, amelyből semmi sem szabadulhat.`),ia(),oa(190,`p`),ky(191,`A medence közepén szigetszerű emelvény magasodott ki a vérből, rajta ősi, rúnákkal borított oszlop állt, a tetején halványan derengő kristállyal. A kristály gyenge, sejtelmes fénye éppen csak megvilágította a medence túlsó oldalát, ahol sötét, boltíves kijárat vált láthatóvá.`),ia(),oa(192,`p`),ky(193,`A kijáratot masszív, faragott kőkeret szegélyezte, amelyet a mennyezetről lelógó vastag gyökerek és pókhálók borítottak. A túloldalra csak a medencén át vezetett út, ahol a sűrű, súlyos vér mozdulatlanul terült el, mintha csak arra várna, hogy elnyelje azokat, akik megpróbálnak átkelni rajta.`),ia(),oa(194,`div`,2),Dd(195,`img`,10),ia(),oa(196,`p`),ky(197,`A boltív mögül szűk, de látszólag biztonságos folyosó indult, amely talán menedéket nyújthatott a vérmedence veszélyei elől. A kristály fénye mintha egyenesen a kijárat felé mutatott volna, jelezve az egyetlen lehetséges menekülési útvonalat.`),ia(),oa(198,`p`),ky(199,`– Ez minden eddiginél rosszabb – mondta Lyrik körülnézve. – Valamiféle szertartási hely lehet. Ez a vér… nem lehet emberi eredetű.`),ia(),oa(200,`p`),ky(201,`– Át kell jutnunk rajta – válaszolta Arkanis, miközben a medencét vizsgálta. – Ez az egyetlen út tovább. Próbáljuk meg először mágiával elérni az oszlopot.`),ia(),oa(202,`p`),ky(203,`Lyrik bólintott, és összpontosítva varázsigét kezdett mormolni. Keze körül halvány derengés jelent meg, és az oszlop előtt lassan kékes fényű portál kezdett formálódni. Ám alighogy kialakult, remegés futott végig rajta, a fény vibrálni kezdett, majd a varázslat egy szempillantás alatt szertefoszlott.`),ia(),oa(204,`p`),ky(205,`– Ez a hely gátolja a térmágiát – mondta Lyrik csalódottan. – Nem lesz ilyen egyszerű eljutni az oszlophoz.`),ia(),oa(206,`p`),ky(207,`– Próbáljuk meg egy híddal – javasolta Arkanis. – Talán egy kézzelfogható építmény áthidalhatja a mágia gyengeségeit. `),ia(),oa(208,`p`),ky(209,`Ezúttal Arkanis kezdett varázslatba, és lassan masszív kőhíd kezdett alakot ölteni fekete sziklákból, pokolkövekből, az oszlop felé nyújtózva. Lyrik sohasem látott még ilyen mágiát, Ardea viszont alig észrevehetően bólintott. A híd szilárdnak tűnt, ahogy egyre tovább nyúlt a vérmedence fölött, de amikor már majdnem elérte az oszlopot, hirtelen megremegett. A vér alól furcsa, mély, zengő hang hallatszott, és a híd kövei lassan összeomlottak, mintha maga a medence élt volna, és elnyelte volna a kődarabokat.`),ia(),oa(210,`p`),ky(211,`– Ez sem fog működni – morogta Arkanis. – Elhihetitek, hogy nem a pancser pyarroni módszert használtam: ez ősi és tiltott tudás volt, olyan, amiért lélekkel kell fizetni. Valami történelem előtti erő gátolja itt a mágiánkat. Csak a saját lábunkon juthatunk el az oszlophoz – summázta kissé paprikásan.`),ia(),oa(212,`p`),ky(213,`Ardea előrelépett, és a medence szélén állva a mozdulatlan vért figyelte. Szigorú tekintettel mérte végig a helyet, majd egy pillanatra elmerengett a természetellenes csendben. – Lehet, hogy ez újabb csapda – mondta halkan. – De nincs más választásunk, át kell kelnünk rajta. El kell érnünk az oszlopot.`),ia(),oa(214,`p`),ky(215,`– Rendben, készüljünk fel – mondta Lyrik. – Legyünk óvatosak, és maradjunk együtt.`),ia(),oa(216,`p`),ky(217,`A csapat tagjai lassan beléptek a medencébe, és ahogy a vér elérte a lábukat, mindannyian megborzongtak a gerincükön végigfutó hidegtől. A vér sűrű és nehéz volt, mintha higanyban gázoltak volna. Minél beljebb jutottak, annál inkább érezték, mintha a medencének nem is volna alja; a vér lassan a mellkasukig ért.`),ia(),oa(218,`p`),ky(219,`– Ez… rosszabb, mint amire számítottam – szólalt meg Isolde. – Mintha élne ez a vér. Érzem, hogy lefelé húz.`),ia(),oa(220,`p`),ky(221,`– Tartsunk össze! – kiáltotta Lyrik. – Ne hagyjuk, hogy elragadjon minket!`),ia(),oa(222,`p`),ky(223,`Ahogy a csapat lassan haladt előre, a vér forrni kezdett körülöttük, mintha valami hatalmas erő ébredezne a mélyben. Áramlása egyre erősödött, hullámokban próbálta elsodorni őket; hol húzta, hol taszította őket, mintha élőlényként akarná megakadályozni, hogy átjussanak.`),ia(),oa(224,`p`),ky(225,`Ekkor Voren és Kael észrevették, hogy a vér tükörré vált, és visszaveri az árnyékukat, ám az árnyékok nem követték a mozdulataikat. Ehelyett önálló életre keltek, és lassan, fenyegetően nőni kezdtek a vér felszínén. A csapat árnyékaiból formálódó sötét alakok tapintható, masszaszerű lényekké váltak.`),ia(),oa(226,`div`,2),Dd(227,`img`,11),ia(),oa(228,`p`),ky(229,`Körülöttük torzulni kezdett a valóság. A csapat tagjai szinte érzékelték, ahogy a tér és az idő elmosódik. Látásuk elhomályosult, mintha a vér nemcsak a testüket, hanem az elméjüket is ostromolta volna. A medence illúziókat vetített a szemük elé, és ezek elbizonytalanították őket. Egy pillanatra mindannyian szem elől tévesztették egymást, a medence szélesebbnek és mélyebbnek tűnt, mint valójában. Lyrik hallotta a többiek kiabálását, de a hangok tompán visszhangoztak, mintha Toronból, több napnyi távolságról hozta volna ide őket az északi szél.`),ia(),oa(230,`p`),ky(231,`Ardea óvatosan haladt előre, és a látomások és illúziók sűrű ködében próbálta megtalálni a valóságot. Mióta Arkanis kéretlenül belelátott a gondolataiba, bosszúra szomjazott. Ez a vágy mélyen gyökerezett benne, és minden lépéssel erősebb lett. Most, hogy elméje egy pillanatra kitisztult a káoszban, a bosszú gondolata villámcsapásként hasított belé: itt az idő, hogy végre leszámoljon Arkanissal.`),ia(),oa(232,`p`),ky(233,`Ardea összeszedte minden szellemi erejét, és elméje pengeként hatolt át az illúziók fátylán, egyenesen Arkanis felé. A nekromanta, aki nemrég az asztrálsíkon megalázta, és kifürkészte a lány minden titkát, most elnyeri méltó büntetését. Ardea ostrom alá vette Arkanis tudatát: át akarta törni a férfi lelki védelmét, és meg akarta semmisíteni lelkének egy részét. Az évek során felgyülemlett dühe és fájdalma most egyetlen hatalmas hullámban zúdult a nekromantára.`),ia(),oa(234,`p`),ky(235,`Arkanis azonnal megérezte a támadást. Elméjében sötét árnyak kezdtek gomolyogni, mintha múltjának legfélelmetesebb kísértetei keltek volna életre: saját bűneinek torz visszhangjai tomboltak a lelkében. Ardea szellemi ereje könyörtelen volt, akár a menekvést nem hagyó vihar. Ahogy egyre mélyebbre hatolt Arkanis tudatába, szörnyű igazság tárult fel előtte: a nekromanta nem csupán sötét lélek volt megannyi gusztustalan és gyomorforgató emlékkel – paktum kötötte egy ősi, rettenetes gonoszhoz, amelynek hatalma minden emberi képzeletet felülmúlt.`),ia(),oa(236,`div`,2),Dd(237,`img`,12),ia(),oa(238,`p`),ky(239,`Ahogy Ardea felfedezte ezt a szörnyűséget, hirtelen eluralkodott rajta a rettegés. – Menekülj, amíg nem késő! – kiáltott belső hangja, de már késő volt. Az ősi entitás, amely Arkanis lelkét uralta, észrevette a támadást, és bosszúálló erővel csapott le. Ez a lény, amely vénebb volt a világ szikláinál és sötétebb az alvilág legmélyebb bugyrainál, egyetlen villámgyors mozdulattal visszavágott.`),ia(),oa(240,`p`),ky(241,`Az erő hirtelen visszacsapott, és Ardea elméjén éles, szinte elviselhetetlen fájdalom hasított végig. Lyrik karjaiba ájult, teste remegett a kíntól, miközben az entitás elérte célját: kitörölt mindent, amit Ardea Arkanisról megtudott. Képességei megmaradtak ugyan, de a nekromanta legnagyobb titkára többé nem emlékezhetett. Az emlékek, amelyekről az imént még biztosan tudta, hogy léteznek, kiperegtek a kezéből, mint homok az ujjai közül.`),ia(),oa(242,`p`),ky(243,`– Nem tudsz megállítani! – sziszegte Arkanis győzelemittas mosollyal. A gonosz erő mélyen átjárta a lelkét, és tovább növelte a hatalmát. Ősi, sötét varázsigét mormolt, amely egyelőre csak Ardea emlékeit sújtotta. – Szívecském, ha túléled, egy héten belül semmivé lesz minden, ami a tudatodból és a személyiségedből megmaradt. – Ardea zavarodottan küzdött a saját tudatával, de a támadás olyan mélyre hatolt, hogy már csak a fájdalom maradt meg, az okát azonban nem tudta többé felidézni. Egyre inkább úgy érezte, mintha köd ereszkedett volna a gondolataira, és lassan, de biztosan eltüntetné mindazt, amit valaha tudott.`),ia(),oa(244,`p`),ky(245,`Arkanis minden erejét összeszedve felélesztette az oszlop körüli rúnákat. Ahogy a rúnák fénye újra felizzott, a vérmedence forrongani kezdett, mintha az ősi gonosz védekezni próbált volna.`),ia(),oa(246,`p`),ky(247,`Amint Arkanis megérintette az oszlop tetején a kristályt, annak fénye hirtelen kialudt. A vér forrongása egy pillanatra alábbhagyott, de a sötétség még nem adta fel. A mélyből újabb erő tört fel, és a vér hirtelen sűrű, ragacsos masszává változott, amely megpróbálta lerántani őket.`),ia(),oa(248,`p`),ky(249,`– Minden erőnket össze kell szednünk! – kiáltotta Arkanis, miközben a kristályt szorította. – Ez az egyetlen esélyünk!`),ia(),oa(250,`p`),ky(251,`A csapat tagjai végső erőfeszítéssel küzdöttek a vérmedence ellen. A ragacsos vér egyre szorosabban fogta őket, de a rúnák fénye lassan eloszlatta az illúziókat, és visszatért körülöttük a valóság.`),ia(),oa(252,`p`),ky(253,`Amikor a vérmedence végül lecsendesedett, a vér lassan visszahúzódott, és a csapat kimerülten rogyott le a medence szélén. A sötétség visszavonult, a kristály pedig lassan újra felragyogott, immár békésebb fénnyel.`),ia(),oa(254,`p`),ky(255,`– Mi történt? – kérdezte Voren, miközben még mindig próbálta megtartani Isoldét. – Miért állt le?`),ia(),oa(256,`p`),ky(257,`– Talán a rúnák felélesztése űzte el a sötét erőt – válaszolta Lyrik, miközben lassan feltápászkodott. – Az oszlop mágikus védelme óvott meg minket. A vérmedence ereje megtört, amikor az oszlop rúnái teljesen működésbe léptek.`),ia(),oa(258,`p`),ky(259,`Arkanis egy pillanatra elmélyedt a gondolataiban, de hamar visszatért a valóságba. – Talán az oszlop arra várt, hogy felismerjük és elfogadjuk a saját félelmeinket. Csak akkor nyílt meg előttünk az út, amikor legyőztük önmagunkat.`),ia(),oa(260,`p`),ky(261,`A nekromanta továbbra is a kristályt figyelte, amely most már nem ragyogott olyan fényesen. – A kristály… valami megváltozott benne. Lehet, hogy elvesztette az erejét, miután legyőztük ezt a helyet. Vigyük magunkkal, talán később még hasznunkra lehet.`),ia(),oa(262,`div`,2),Dd(263,`img`,13),ia(),oa(264,`p`),ky(265,`Arkanis letörte a kristályt az oszlop tetejéről, és egy kis bőrzsákba tette. Ahogy a kristály eltűnt, a hely egyre nyugodtabbnak tűnt, de a csapat nem bízott a látszatban. Mindannyian tudták, hogy ez csak a vihar előtti csend lehet.`),ia(),oa(266,`p`),ky(267,`– Akárhogy is, túl vagyunk rajta – mondta Lyrik, és végignézett a csapatán. – Menjünk tovább. A vérmedencénél rosszabbat is meg kell még élnünk, ha el akarjuk érni a célunkat.`),ia(),oa(268,`p`),ky(269,`Amikor a csapat elérte a medence túloldalán nyíló kijáratot, mindannyian érezték, hogy valami megváltozott. A medence, amely az imént még el akarta ragadni őket, most nyugodtnak tűnt, de a hely sötét ereje továbbra is ott lappangott a háttérben.`),ia(),oa(270,`p`),ky(271,`Ahogy továbbindultak, mindannyian magukon viselték a vérmedence nyomát. Sebeik és lelki megpróbáltatásaik mélyen beléjük vésődtek, de tudták, hogy nincs visszaút.`),ia()(),oa(272,`section`)(273,`h2`),ky(274,`Az Élő Labirintus`),ia(),oa(275,`p`),ky(276,`A csapat tagjai testükön és lelkükön a Vérmedence sebeivel haladtak előre a sötét alagútban. A folyosó végén hatalmas, boltíves terem tárult eléjük, amelynek falai lágyan pulzáltak, mintha élnének. A levegő sűrű volt és fojtogató, mintha valami óriási lény lélegezne körülöttük.`),ia(),oa(277,`p`),ky(278,`A terem közepén lüktető, organikus építmény magasodott, körülötte különös kapu lebegett a levegőben. A kapu zárva volt, és mintha az egész terem a csapatra összpontosította volna a figyelmét. Az építmény fölött sötéten izzó kristály lebegett, fénye sejtelmesen villódzott a félhomályban.`),ia(),oa(279,`p`),ky(280,`Arkanis azonnal megérezte a mágia jelenlétét, és tekintete a kristályra szegeződött.`),ia(),oa(281,`p`),ky(282,`– Ez a kristály kapcsolatban áll a Vérmedencéből hozottal – mondta halkan, és elővette bőrzsákjából a zsákmányt. Ahogy közelebb lépett a terem közepén lebegő kristályhoz, a kettejük közötti kapcsolat szinte tapinthatóvá vált.`),ia(),oa(283,`div`,2),Dd(284,`img`,14),ia(),oa(285,`p`),ky(286,`Isolde körbejárta a termet, keze a rapírja markolatán pihent.`),ia(),oa(287,`p`),ky(288,`– Ez a hely él – suttogta. – De hogy mik a szándékai, azt még nem tudjuk.`),ia(),oa(289,`p`),ky(290,`Ardea Myranda szemmel tartotta a kristályt és a körülötte lebegő energiákat.`),ia(),oa(291,`p`),ky(292,`– Ez nem egyszerű mágiaforrás. Maga a terem is része a varázslatnak. A kérdés az, hogy mi nyitja meg a kaput – tűnődött.`),ia(),oa(293,`p`),ky(294,`Lyrik lassan megérintette a pulzáló falat, amely egy pillanatra visszahúzódott az érintése elől.`),ia(),oa(295,`p`),ky(296,`– Mintha lélegezne… Mintha figyelne ránk.`),ia(),oa(297,`p`),ky(298,`Voren és Kael figyelmesen tanulmányozták a falakon megjelenő rúnákat.`),ia(),oa(299,`p`),ky(300,`– Ezek a jelek – kezdte Voren – valami régi szertartás részei lehetnek. De nem egészen világos, mit jelentenek.`),ia(),oa(301,`p`),ky(302,`Kael bólintott.`),ia(),oa(303,`p`),ky(304,`– Valószínűleg a kristályok hatására kelnek életre. De hogyan nyithatnánk ki velük a kaput? `),ia(),oa(305,`p`),ky(306,`Arkanis mély levegőt vett, és lassan felemelte a Vérmedencéből hozott kristályt. A két kő közötti kapcsolat hirtelen megerősödött, és halvány energiafonál feszült közéjük. Ahogy a távolság csökkent köztük, a fonál fokozatosan erősödött, majd egyenesen a terem falai felé fordult.`),ia(),oa(307,`p`),ky(308,`A terem hirtelen megmozdult, és a falak alakot váltottak, mintha a kristály irányította volna őket. Az egész terem bonyolult, mozgó labirintussá alakult, amely szüntelenül változtatta a formáját. A falak összezárultak, majd újra szétnyíltak, mintha el akarták volna zárni az utat a csapat elől.`),ia(),oa(309,`div`,2),Dd(310,`img`,15),ia(),oa(311,`p`),ky(312,`– Ez nem jó jel – morogta Lyrik, és ösztönösen tűzvarázslatra készült, bár tudta, hogy nem ez lesz a megoldás. – Arkanis, te vagy az egyetlen, aki irányítani tudja ezt a helyet. Próbáld meg újra!`),ia(),oa(313,`p`),ky(314,`Arkanis ismét összpontosított, és a Vérmedencéből származó kristályt a középpont felé tartotta. A két kristály közötti kapcsolat még erősebb lett, és a terem falai ismét engedelmeskedtek. Az egyik fal szétvált, és újabb járat tárult fel, amely a labirintus belsejébe vezetett.`),ia(),oa(315,`p`),ky(316,`Isolde gyorsan levonta a következtetést:`),ia(),oa(317,`p`),ky(318,`– Mindenki figyeljen! Úgy tűnik, a kristály engedelmeskedik nekünk, de csak akkor, ha helyesen használjuk.`),ia(),oa(319,`div`,2),Dd(320,`img`,16),ia(),oa(321,`p`),ky(322,`A csapat lassan haladt előre Arkanis nyomában. A labirintus szüntelenül változott, a falak újabb és újabb csapdákat állítottak, de Arkanis a kristály segítségével mindig megnyitotta előttük az utat. `),ia(),oa(323,`p`),ky(324,`Pár perc pihenő következett.`),ia(),oa(325,`p`),ky(326,`Ardea Myranda mély lélegzetet vett, de érezte, hogy ereje és tudata lassan megroppan. Arkanis varázslatának hatása alatt is próbált kapaszkodni az elméjébe, de a sötét energia fokozatosan elhomályosította a gondolatait. Isolde ekkor közelebb lépett hozzá, és egy pillanatra a szemébe nézett.`),ia(),oa(327,`p`),ky(328,`– Ardea… – suttogta Isolde, és finoman végigsimított a nő arcán. – Ne veszítsd el önmagad! Maradj velem, kedves!`),ia(),oa(329,`p`),ky(330,`Ardea szíve megdobbant, és a fájdalom egy pillanatra alábbhagyott. Soha senkit nem engedett közel magához, de Isolde más volt. Mindketten tudták, hogy a sorsuk nem engedi beteljesülni azt, ami köztük lehetett volna, ebben a pillanatban mégis, a sötétség szorításában, úgy érezték, mintha egy másik világban léteznének, ahol mindez lehetséges.`),ia(),oa(331,`p`),ky(332,`Isolde közelebb húzódott, és gyengéden megcsókolta Ardeát. A csók rövid volt, de benne volt mindaz az elfojtott érzés és vágy, amelyet soha nem vallhattak meg egymásnak. Ardea lassan lehunyta a szemét, és egy könnycsepp gördült végig az arcán, ahogy érezte, hogy a tudatát körülvevő sötétség visszatér.`),ia(),oa(333,`p`),ky(334,`– Nem engedlek el! – suttogta Isolde eltökélten. – Veled maradok a legvégsőkig, bármi történjék is.`),ia(),oa(335,`p`),ky(336,`– Tudom – válaszolta Ardea halkan. – Majd talán egy másik világban, egy másik életben…`),ia(),oa(337,`p`),ky(338,`Isolde bólintott, de nem szólt többet. Tisztában voltak vele, hogy ez az érzés soha nem teljesedhet be. Mégis, abban a röpke pillanatban, amikor egymásra találtak, talán egy kis menedékre leltek a sötétség elől.`),ia(),oa(339,`p`),ky(340,`A szerelmet azonban nem állhatta ez a gonosz hely, és légköre könyörtelenül szétzúzta a pillanatot. A falak mintha egyre közelebb húzódtak volna, a levegő sűrűbbé vált, mintha az egész terem el akarta volna nyelni őket.`),ia(),oa(341,`p`),ky(342,`– Most vagy soha! – kiáltotta Voren, és testvére, Kael, mellé állt. Együtt emelték fel fegyverüket, mintha valami ősi rítust hajtanának végre. A pengéken felragyogtak a rúnák, és rezgés futott végig a levegőn, amely egy rövid pillanatra megállította a falak mozgását.`),ia(),oa(343,`p`),ky(344,`Isolde kihasználta az alkalmat, és előrelépett.`),ia(),oa(345,`p`),ky(346,`– Ez a terem érzékeny a mágiára, de csak akkor enged, ha összhangban cselekszünk. Arkanis, Lyrik, Ardea! Mindannyiunknak egyszerre kell varázsolnunk!`),ia(),oa(347,`p`),ky(348,`Ardea Myranda mély lélegzetet vett, és a kardját a talajba döfte. A penge körül vöröses, sötét aura emelkedett fel, amely szinte azonnal összekapcsolódott Arkanis kristályával. Lyrik a lángok erejével fokozta a feszültséget, és a falak ismét megremegtek, mintha a terem ellenállt volna a rájuk zúduló erőknek.`),ia(),oa(349,`p`),ky(350,`– Most! – kiáltotta Lyrik, és a csapat egyszerre összpontosította minden erejét. Arkanis kristálya vakító fénnyel lobbant fel, és a két kristály közötti kapcsolat hatalmas energiahullámot indított el. A falak hirtelen visszahúzódtak, és a terem közepén lebegő kapu lassan kinyílt.`),ia(),oa(351,`div`,2),Dd(352,`img`,17),ia(),oa(353,`p`),ky(354,`A csapat kimerülten, de diadalmasan lépett át a kapun. A labirintus visszahúzódott, és a kristályok fénye lassan elhalványult, mintha a terem beismerte volna vereségét.`),ia(),oa(355,`p`),ky(356,`Ahogy továbbhaladtak, Voren csendesen megszólalt, szemét a Vérmedencéből szerzett kristályon tartva:`),ia(),oa(357,`p`),ky(358,`– Lehet, hogy ez a kristály több annál, aminek látszik… Talán lélekkő, amely egy ősi entitás hatalmát rejti?`),ia(),oa(359,`p`),ky(360,`A többiek egy pillanatra megdermedtek. Arkanis szigorúan Vorenre nézett, és bár elméjével szét tudta volna tépni a nyikhajt, végül végtelen, bárgyú nyugalmat erőltetve az arcára így felelt:`),ia(),oa(361,`p`),ky(362,`– Az Éjkő létezik, Voren. Ne hagyd, hogy a kétségeid elvakítsanak. A mi dolgunk most, hogy használjuk az erejét. `),ia(),oa(363,`p`),ky(364,`Isolde csendesen bólintott, de egy pillanatra visszanézett Vorenre, mintha a hallottakon töprengene. A csapat lassan továbbhaladt, Voren szavai azonban ott maradtak a levegőben, és halk kételyt ültettek a többiek szívébe.`),ia()(),oa(365,`section`)(366,`h2`),ky(367,`A Végső Szembesülés`),ia(),oa(368,`p`),ky(369,`A csapat kimerülten haladt tovább az alagút mélyén, minden lépéssel közelebb kerülve a végzetéhez. Az eddigi csapdák – az árnydémonok támadása, a Vérmedence baljós illúziói és az Élő Labirintus mozgó falai – mindannyiukat megviselték. Testük és lelkük egyaránt megroppant, de mélyről fakadó, ösztönös elszántság hajtotta őket előre. A levegő egyre sűrűbb és nyomasztóbb lett, mintha maga az alagút próbálta volna visszatartani őket. Minden lépés nehezebb volt az előzőnél, de tudták, hogy nincs visszaút.`),ia(),oa(370,`div`,2),Dd(371,`img`,18),ia(),oa(372,`p`),ky(373,`Hirtelen, mintha az alagút falai maguktól húzódtak volna szét, óriási csarnok tárult eléjük, nagyobb mindennél, amit addig láttak. A falakat mélyen faragott rúnák és sötét, lüktető erek borították, mintha magából a kőből nőttek volna ki. A mennyezet magasan a fejük fölött húzódott, és a távolban alig lehetett kivenni, hol ér véget a csarnok. Közepén hatalmas, sötét alak magasodott, amelyből mintha maga a sötétség sugárzott volna. A levegő megfagyott körülöttük, a csend szinte fülsüketítő volt.`),ia(),oa(374,`div`,2),Dd(375,`img`,19),ia(),oa(376,`p`),ky(377,`– Ez… ez nem lehet igaz – suttogta Isolde, miközben remegő lábbal belépett a csarnokba. Szeme tágra nyílt, ahogy a sötét alakra meredt, amely most már tisztán kivehető volt. – Ez az a lény, amelyről a legendák mesélnek. A Mana-nyelő…`),ia(),oa(378,`p`),ky(379,`Arkanis komor tekintettel bámulta a lényt, de belül öröm töltötte el, amelyet gondosan elrejtett társai elől. – Ez a terem maga a pokol kapuja. Érzem a hatalmát, szinte átszivárog a falakon. Ez a hely nem egyszerű csapda: egy ősi erő börtöne, amelyet azért zártak ide, hogy ne szabadulhasson ki.`),ia(),oa(380,`p`),ky(381,`Lyrik, a tűzvarázsló, előrelépett, és minden bátorságát összeszedve nézett szembe a lénnyel. – Mégis itt van előttünk. És ha itt van, talán van módunk visszatartani vagy legyőzni.`),ia(),oa(382,`p`),ky(383,`Arkanis mosolyt erőltetett magára, mintha egyetértene, de magában már a perceket számolta, amíg eléri végső célját. Az egész küldetés, az Éjkő keresése mindvégig értelmetlen volt. Ő tudta ezt, hiszen maga is része volt a Mana-nyelő tervének. Közeledett az igazság pillanata.`),ia(),oa(384,`p`),ky(385,`– Ez a hely tele van csapdákkal – mondta Ardea körülnézve. – Nem tudhatjuk, mi történik, ha támadunk.`),ia(),oa(386,`p`),ky(387,`– Nem hagyhatjuk, hogy ez a lény kijusson innen – mondta Lyrik határozottan, majd közelebb lépett egy oszlophoz, amely a lény előtt magasodott. Az oszlop tetején fekete kristály ült, amely mintha minden fényt elnyelt volna. – Talán ebből a kristályból táplálkozik az ereje. Ha elpusztítjuk, őt is legyőzhetjük.`),ia(),oa(388,`p`),ky(389,`– Nem tudom, legyőzhetjük-e – mondta Ardea, és minden erejével igyekezett hinni a saját szavaiban. – De nem adhatjuk fel. Idáig eljutottunk, nem hagyhatjuk, hogy mindez hiábavaló legyen.`),ia(),oa(390,`p`),ky(391,`Ahogy közelebb értek az oszlophoz, a Mana-nyelő hirtelen megmozdult. Az árnyak, amelyek körülvették, életre keltek, és mintha magukba akarták volna szippantani a csapatot.`),ia(),oa(392,`p`),ky(393,`– Vigyázzatok! – kiáltotta Arkanis, de hangjában nem volt valódi aggodalom. Sötét varázslatot idézett, mintha vissza akarná tartani az árnyakat, de azok túlságosan erősek voltak, és lassan bekerítették a csapatot.`),ia(),oa(394,`div`,2),Dd(395,`img`,20),ia(),oa(396,`p`),ky(397,`A csapat vállt vállnak vetve küzdött a lény ellen. Lyrik tűzlabdákat szórt, Isolde rapírjai villámgyorsan suhantak, Voren és Kael szinte egy emberként mozogtak, Ardea pedig sötét energiákat idézett, hogy visszaszorítsa a lényt. A küzdelem hősies volt, de a Mana-nyelő hatalma minden képzeletüket meghaladta.`),ia(),oa(398,`p`),ky(399,`– Ez nem működik – mondta Voren kétségbeesetten. – Nem tudjuk megállítani.`),ia(),oa(400,`p`),ky(401,`Isolde imát mormolt, mintha abban keresné a megoldást, de Arkanis tudta, hogy semmi sem segít. A csapda tökéletesen működött, már csak az utolsó lépés volt hátra. – Nincs ellenmágia, amely segítene – mondta mesterkélt szomorúsággal.`),ia(),oa(402,`p`),ky(403,`Lyrik az utolsó reménysugárba kapaszkodva a fekete kristályhoz lépett, hogy összezúzza, de mielőtt megérinthette volna, a Mana-nyelő megszólalt – hangja mintha a fejükben visszhangzott volna.`),ia(),oa(404,`p`),ky(405,`– Az Éjkő sosem létezett számotokra: az az én lélekkövem volt, hatalmam kulcsa – zúgta a lény. – Az Éjkő meséje csak csalétek volt, hogy idecsaljalak benneteket. Köszönöm nektek, ti kalandozók, akiknek ereje elegendő volt ahhoz, hogy meggyengítsétek a börtönömet. Most, hogy itt vagytok, nincs menekvés. Jutalmul csak a gyors halált kapjátok, és azt, hogy elmondhatjátok: ti tápláltátok az újjászületésemet. Mindannyian el fogtok pusztulni, mert a szabadulásom záloga vagytok.`),ia(),oa(406,`p`),ky(407,`Arkanis diadalmasan nézett körül. – Minden úgy történt, ahogy elrendeltetett – mondta, felfedve valódi szándékait. – Én magam is a terv része voltam. A megrendelő, aki ezt a küldetést adta, nem más volt, mint a Mana-nyelő asztrális kivetülése. Mindannyian csupán eszközök voltatok a lény kiszabadításához.`),ia(),oa(408,`p`),ky(409,`A csapat tagjai döbbenten meredtek rá, miközben a sötétség egyre inkább elnyelte őket. Tudták, hogy nincs menekvés, nincs ellenmágia, amely segíthetne. Végzetük elkerülhetetlen volt.`),ia(),oa(410,`p`),ky(411,`Ahogy a sötétség körülölelte őket, a csapat tagjai lassan összeroskadtak, mintha a lény kiszívta volna belőlük az életet. Lyrik még megpróbált egy utolsó varázslatot előhívni, de elhagyta az ereje. A tűz, amely mindig is lángolt benne, most végleg kialudt.`),ia(),oa(412,`p`),ky(413,`Isolde arca eltorzult a fájdalomtól, ahogy térdre rogyott. Próbált imádkozni, de a szavak elhaltak az ajkán. Ellana, az istennő, akit szolgált, nem hallotta meg fohászát ezen a sötét, elátkozott helyen.`),ia(),oa(414,`p`),ky(415,`Voren és Kael megpróbáltak egymás felé nyúlni, de a sötétség áthatolhatatlan falként állt közéjük. Testvérek voltak, harcosok, most mégis tehetetlenek. A sötétségben elvesztették egymást és minden reményüket.`),ia(),oa(416,`p`),ky(417,`Ardea Myranda, aki mindig is a sötétségből merítette erejét, most rádöbbent, hogy ez a sötétség hatalmasabb mindennél, amit valaha ismert. Kardja, amely annyi ellenséget levágott, most súlytalannak tűnt, és nem maradt ereje tovább küzdeni.`),ia(),oa(418,`div`,2),Dd(419,`img`,21),ia(),oa(420,`p`),ky(421,`Isolde elérte Ardeát, utolsó erejével maga felé fordította, majd gyengéden megcsókolta. Érintésükben ott volt minden el nem mondott szó, minden vágy és remény, amelyet sosem vallottak be egymásnak. Ahogy ajkuk elvált, mindketten tudták, hogy sorsuk megpecsételődött, de a szerelem, amelyet egymás iránt éreztek, még a halál árnyékában is ott ragyogott.`),ia(),oa(422,`p`),ky(423,`– Együtt megyünk tovább – suttogta Isolde, miközben ujjait összefűzte Ardeáéval.`),ia(),oa(424,`p`),ky(425,`Ardea gyengéden megszorította Isolde kezét, majd mindketten bevégezték.`),ia(),oa(426,`p`),ky(427,`Arkanis a csapat utolsó sóhajait figyelte, ahogy a sötétség végleg magába szippantotta őket. Ő maga sem menekült meg, de nem is akart. Számára ez volt a legnagyobb diadal: az ő segítségével szabadult ki a Mana-nyelő, és most már semmi sem állíthatta meg. Ahogy a sötétség őt is elnyelte, egy pillanatra érezte a halál rideg ölelését – de ez a halál nem volt végleges. Arkanis lelke örökre a Mana-nyelő rabszolgája lett, árnyék a lény végtelen sötétségében.`),ia(),oa(428,`p`),ky(429,`A csarnok ismét csendbe burkolózott. A rúnák lassan elhalványultak, és a sötétség visszahúzódott. A Mana-nyelő teljes ereje visszatért, és a lény végleg kiszakította magát a börtönéből. Szabaddá vált, és vele együtt a pusztítás szele is, amely az egész világot elnyeléssel fenyegette.`),ia(),oa(430,`p`),ky(431,`A lény elhagyta a csarnokot, és vele együtt a sötétség is előkúszott a mélyből. A föld megremegett, és az alagút, amely eddig börtönként szolgált, most a pusztulás méhévé vált. Arkanis mindig is tudta, hogy a sötétség nem ismer határokat, és mindent elnyel, ami az útjába kerül.`),ia(),oa(432,`p`),ky(433,` Egész életében ezt vallotta: „Jobb a gonosz szolgájának lenni, mint az útjában állni.” `),ia()(),oa(434,`section`)(435,`h1`,1),ky(436,`VÉGE`),ia()()())},styles:[`.page-body[_ngcontent-%COMP%]{font-family:MedievalSharp,serif;background-color:#1a1a1a;color:#dcdcdc;line-height:1.8;margin:0;padding:0;text-shadow:1px 1px 2px #000;font-size:2rem}h1[_ngcontent-%COMP%], h2[_ngcontent-%COMP%], h3[_ngcontent-%COMP%]{font-family:Ga Maamli,sans-serif;color:#b8860b;text-shadow:2px 2px 4px #000;margin-bottom:20px}h1[_ngcontent-%COMP%]{font-size:3em;margin-top:40px}h2[_ngcontent-%COMP%]{font-size:2.5em;margin-top:30px}h3[_ngcontent-%COMP%]{font-size:2em;margin-top:20px}p[_ngcontent-%COMP%]{margin-bottom:20px}.vege[_ngcontent-%COMP%]{max-width:fit-content;margin-left:auto;margin-right:auto}a[_ngcontent-%COMP%]{color:#ff4500;text-decoration:none;border-bottom:2px dotted #ff4500;transition:color .3s ease,border-bottom .3s ease}a[_ngcontent-%COMP%]:hover{color:tomato;border-bottom:2px solid #ff6347}blockquote[_ngcontent-%COMP%]{font-style:italic;background-color:#2b2b2b;border-left:5px solid #b8860b;margin:20px 0;padding:20px;color:#e6e6e6;text-shadow:1px 1px 3px #000}section[_ngcontent-%COMP%]{margin:40px 0;padding:30px;background:#000000bf;border-radius:15px;box-shadow:0 0 20px #000000e6}img[_ngcontent-%COMP%]{max-width:100%;height:auto;border:5px solid #3b3b3b;border-radius:10px;box-shadow:0 0 15px #000000d9}.center[_ngcontent-%COMP%]{text-align:center}button[_ngcontent-%COMP%]{background-color:#333;color:#b8860b;padding:10px 20px;border:2px solid #b8860b;border-radius:5px;font-family:Ga Maamli,sans-serif;font-size:1.2em;cursor:pointer;text-shadow:1px 1px 2px #000;transition:background-color .3s ease,color .3s ease,border-color .3s ease}button[_ngcontent-%COMP%]:hover{background-color:#b8860b;color:#333;border-color:#dcdcdc}.image-placeholder[_ngcontent-%COMP%]{width:50%;height:50%;max-width:fit-content;margin-left:auto;margin-right:auto;background:#e0e0e0;border:2px dashed #2c2c2c;display:flex;align-items:center;justify-content:center;font-size:1.5em;color:#2c2c2c;position:relative;overflow:hidden;border-radius:10px;box-shadow:0 0 20px #00000080}.image-placeholder[_ngcontent-%COMP%]   img[_ngcontent-%COMP%]{width:100%;height:auto;transition:transform .5s,filter .5s;filter:brightness(.8)}.image-placeholder[_ngcontent-%COMP%]   img[_ngcontent-%COMP%]:hover{transform:scale(1.05);filter:brightness(1)}`]})}}return E})();export{o as ManaNyeloComponent};